App.my.KEY = 'charges';
App.my.list = () => App.items(App.my.KEY).slice().sort((a, b) => (b.date || '').localeCompare(a.date || '') || b.at - a.at);
App.my.month = (key) => App.items(App.my.KEY).filter((c) => App.monthKey(c.date) === key);
App.my.sum = (list, f) => list.reduce((s, c) => s + (Number(c[f]) || 0), 0);
App.my.perKm = () => {
  const l = App.items(App.my.KEY).filter((c) => Number(c.odo) > 0).sort((a, b) => Number(a.odo) - Number(b.odo));
  if (l.length < 2) return null;
  const km = Number(l[l.length - 1].odo) - Number(l[0].odo);
  const cost = App.my.sum(l.slice(1), 'cost');
  return km > 0 ? cost / km : null;
};

App.my.widget = async () => {
  const now = App.my.month(App.monthKey(new Date()));
  try { await App.widget('⚡ ఛార్జింగ్', ['ఈ నెల: ' + App.rs(App.my.sum(now, 'cost')), App.n(App.my.sum(now, 'units'), 1) + ' యూనిట్లు · ' + now.length + ' సార్లు']); } catch (e) { /* the widget only helps */ }
};
App.onStart(() => { App.my.widget(); });
App.onJarvis('add', (d) => {
  const units = Number(d.units), cost = Number(d.cost);
  if (!(units > 0) && !(cost > 0)) return 'యూనిట్లు, ఖర్చు రెండూ లేవు; ఏమీ రాయలేదు';
  const rec = { date: /^\d{4}-\d{2}-\d{2}$/.test(String(d.date || '')) ? d.date : App.today(), units: units > 0 ? units : 0, cost: cost >= 0 ? cost : 0,
    from: 0, to: 0, odo: Number(d.odo) > 0 ? Number(d.odo) : 0 };
  App.add(App.my.KEY, rec);
  App.my.widget();
  return App.n(rec.units, 1) + ' యూనిట్లు ' + App.rs(rec.cost) + ' రాశాను';
});

App.onShow('home', () => {
  const now = App.my.month(App.monthKey(new Date()));
  App.text('#home-month', App.rs(App.my.sum(now, 'cost')));
  App.text('#home-units', App.n(App.my.sum(now, 'units'), 1));
  const l = App.my.list();
  App.set('#home-list', l.length ? '<div class="list">' + l.map((c) => `
    <div class="item" data-id="${App.esc(c.id)}">
      <div class="ic">⚡</div>
      <div class="w"><div class="t">${App.esc(App.n(c.units, 1))} యూనిట్లు${c.from || c.to ? ' · ' + App.esc(c.from || 0) + '% → ' + App.esc(c.to || 0) + '%' : ''}</div>
        <div class="s">${App.date(c.date)}${c.odo ? ' · ' + App.esc(App.n(c.odo)) + ' km' : ''}</div></div>
      <div class="r">${App.rs(c.cost)}</div>
    </div>`).join('') + '</div>'
    : '<div class="empty"><div class="e">🔌</div>ఇంకా ఛార్జింగ్ రాయలేదు. + నొక్కి రాయండి.</div>');
});
App.click('#home-add', () => App.go('add'));
App.click('#home-list .item', (ev, el) => App.go('add', App.find(App.my.KEY, el.dataset.id)));

App.onShow('add', (c) => {
  App.my.editing = c && c.id ? c.id : null;
  App.title(App.my.editing ? 'ఛార్జింగ్ మార్చండి' : 'ఛార్జింగ్ రాయండి');
  App.val('#add-date', c && c.date ? c.date : App.today());
  App.val('#add-units', c ? c.units : '');
  App.val('#add-cost', c ? c.cost : '');
  App.val('#add-from', c ? c.from : '');
  App.val('#add-to', c ? c.to : '');
  App.val('#add-odo', c ? c.odo : '');
  App.show('#add-del', !!App.my.editing);
});
App.click('#add-save', () => {
  const units = Number(App.val('#add-units')), cost = Number(App.val('#add-cost'));
  if (!(units > 0)) { App.toast('ఎన్ని యూనిట్లో రాయండి'); return; }
  if (!(cost >= 0)) { App.toast('ఖర్చు సరిగా రాయండి'); return; }
  const rec = { date: App.val('#add-date') || App.today(), units, cost, from: Number(App.val('#add-from')) || 0, to: Number(App.val('#add-to')) || 0, odo: Number(App.val('#add-odo')) || 0 };
  if (App.my.editing) App.update(App.my.KEY, App.my.editing, rec); else App.add(App.my.KEY, rec);
  App.my.widget();
  App.beep('ok');
  App.toast('దాచాను');
  App.back();
});
App.click('#add-del', async () => {
  if (!App.my.editing) return;
  if (await App.ask('ఈ ఛార్జింగ్ తీసేయాలా?', 'తీసేయి', 'వద్దు')) { App.del(App.my.KEY, App.my.editing); App.my.widget(); App.toast('తీసేశాను'); App.back(); }
});

App.onShow('stats', () => {
  const pk = App.my.perKm();
  App.text('#stats-km', pk == null ? '—' : App.rs(pk));
  App.text('#stats-count', App.items(App.my.KEY).length + ' సార్లు');
  const keys = [];
  for (let i = 5; i >= 0; i--) { const d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - i); keys.push(App.monthKey(d)); }
  App.chart('#stats-chart', { type: 'bar', labels: keys.map((k) => App.month(k + '-01').split(' ')[0]), values: keys.map((k) => App.my.sum(App.my.month(k), 'cost')), money: true });
});

App.my.nextSunday = () => {
  const d = new Date(); d.setHours(20, 0, 0, 0);
  let add = (7 - d.getDay()) % 7;
  if (add === 0 && d.getTime() < Date.now()) add = 7;
  d.setDate(d.getDate() + add);
  return d.getTime();
};
App.my.drawRem = async () => {
  let on = false;
  try { on = (await App.reminders()).some((r) => r.id === 'weekly'); } catch (e) { /* */ }
  App.my.remOn = on;
  App.text('#stats-rem', on ? 'తీసేయి' : 'పెట్టు');
  App.text('#stats-rem-s', on ? 'పెట్టారు: ప్రతి ఆదివారం రాత్రి 8 కి' : 'ఆదివారం రాత్రి 8 కి "ఈ వారం ఛార్జింగ్‌లు రాశారా?" అని');
};
App.onShow('stats', () => { App.my.drawRem(); });
App.click('#stats-rem', async () => {
  try {
    if (App.my.remOn) { await App.unremind('weekly'); App.toast('రిమైండర్ తీసేశాను'); }
    else {
      await App.remind({ id: 'weekly', when: App.my.nextSunday(), every: 'week', title: '⚡ ఛార్జింగ్ లాగ్', text: 'ఈ వారం ఛార్జింగ్‌లు రాశారా?', screen: 'add' });
      App.toast('ప్రతి ఆదివారం రాత్రి 8 కి గుర్తు చేస్తాను');
    }
  } catch (e) { App.toast('రిమైండర్ పెట్టలేకపోయాను'); }
  App.my.drawRem();
});
App.my.thisMonth = () => App.my.month(App.monthKey(new Date())).sort((a, b) => (a.date || '').localeCompare(b.date || ''));
App.click('#stats-share', async () => {
  const l = App.my.thisMonth();
  const t = '⚡ ' + App.month(App.today()) + ' ఛార్జింగ్: ' + l.length + ' సార్లు, ' + App.n(App.my.sum(l, 'units'), 1) + ' యూనిట్లు, ' + App.rs(App.my.sum(l, 'cost'))
    + (App.my.perKm() != null ? '\nఒక km కి: ' + App.rs(App.my.perKm()) : '');
  try { await App.share(t); } catch (e) { App.toast('షేర్ కాలేదు'); }
});
App.click('#stats-pdf', async () => {
  const l = App.my.thisMonth();
  const rows = l.map((c) => `<tr><td>${App.date(c.date, 'short')}</td><td class="n">${App.n(c.units, 1)}</td><td class="n">${App.rs(c.cost)}</td><td class="n">${c.from || c.to ? App.esc(c.from || 0) + '% → ' + App.esc(c.to || 0) + '%' : ''}</td><td class="n">${c.odo ? App.n(c.odo) : ''}</td></tr>`).join('');
  const html = `<h2>${App.esc(App.month(App.today()))} ఛార్జింగ్</h2><p>${l.length} సార్లు · ${App.n(App.my.sum(l, 'units'), 1)} యూనిట్లు · <b>${App.rs(App.my.sum(l, 'cost'))}</b></p>`
    + `<table><tr><th>తేదీ</th><th>యూనిట్లు</th><th>ఖర్చు</th><th>బ్యాటరీ</th><th>km</th></tr>${rows}</table>`;
  try { await App.pdf('ఛార్జింగ్ ' + App.monthKey(new Date()), html); } catch (e) { App.toast('PDF కాలేదు'); }
});
